process.env.COMPILER_RUNS ??= '5';
process.env.COMPILER_ITERATIONS ??= '5';
process.env.COMPILER_OUTPUT ??= join(
  lab,
  process.env.CAMPAIGN_OUTPUT ?? 'local-micro',
);
await import(pathToFileURL(runnerPath));

