    };
    const dist = join(output, 'dist', label),
      decisions = [];
    const started = performance.now();
    await build({
      configFile: false,
      root: app,
      logLevel: 'error',
      plugins: [
        ...(process.env.CAMPAIGN_LOCAL_FIXTURE === 'true' || process.env.CAMPAIGN_SCALAR_FIXTURE === 'true' || process.env.CAMPAIGN_IMPORTED_FIXTURE === 'true' || process.env.CAMPAIGN_WIDE_INDEX === 'true' || process.env.CAMPAIGN_SERVICE_FIXTURE === 'true' ? [{
          name:'campaign-local-fixture', enforce:'pre',
          resolveId(specifier){if(specifier==='campaign-imported-rows')return "/Users/romaingeffrault/Documents/projects/prive/craft-ts-imperative-render/tmp/performance-campaign/imported-fixture/rows.ts";},
          transform(source,id) {
            if(id !== join(app,'main.ts')) return null;
            if(process.env.CAMPAIGN_IMPORTED_FIXTURE === 'true') {
