        ...(process.env.CAMPAIGN_LOCAL_FIXTURE === 'true' || process.env.CAMPAIGN_SCALAR_FIXTURE === 'true' || process.env.CAMPAIGN_IMPORTED_FIXTURE === 'true' || process.env.CAMPAIGN_WIDE_INDEX === 'true' || process.env.CAMPAIGN_SERVICE_FIXTURE === 'true' ? [{
          name:'campaign-local-fixture', enforce:'pre',
          resolveId(specifier){if(specifier==='campaign-imported-rows')return "/Users/romaingeffrault/Documents/projects/prive/craft-ts-imperative-render/tmp/performance-campaign/imported-fixture/rows.ts";},
          transform(source,id) {
            if(id !== join(app,'main.ts')) return null;
            if(process.env.CAMPAIGN_IMPORTED_FIXTURE === 'true') {
              const start=source.indexOf('const Row = craftComponent('),end=source.indexOf('const Leaf = craftComponent(');
              source="import {Row,IndexedRow} from 'campaign-imported-rows';\n"+source.slice(0,start)+source.slice(end);
            }
            if(process.env.CAMPAIGN_SCALAR_FIXTURE === 'true') {
              const start=source.indexOf('const Row = craftComponent('), end=source.indexOf('const IndexedRow = craftComponent(');
              source=source.slice(0,start)+"const Row=craftComponent('CompilerBenchRow',{},(inputs:{row:Input<string>;position:Input<number>})=>div({'data-row':inputs.row},inputs.row));\n"+source.slice(end);
              source=source.replace('(row, position) => Row({ row, position })','(row, position) => Row({ row: row.label, position })');
            }
            if(process.env.CAMPAIGN_WIDE_INDEX === 'true') {
              const start=source.indexOf('const IndexedRow = craftComponent('),end=source.indexOf('const Leaf = craftComponent(');
              if(start<0||end<0)throw Error('Wide index anchors missing');
              const cells=Array.from({length:16},()=>"span({'data-position':inputs.position},function*(){return (yield* inputs.position())+1;})");
              source=source.slice(0,start)+"const IndexedRow=craftComponent('CompilerBenchIndexedRow',{},(inputs:{row:Input<{id:number;label:string}>;position:Input<number>})=>div({'data-row':function*(){return (yield* inputs.row()).id;}},["+cells.join(',')+",function*(){return (yield* inputs.row()).label;}]));\n"+source.slice(end);
            }
            if(process.env.CAMPAIGN_SERVICE_FIXTURE === 'true') {
              const start=source.indexOf('const Row = craftComponent('),end=source.indexOf('const IndexedRow = craftComponent(');
              if(start<0||end<0)throw Error('Service fixture anchors missing');
              source=source.slice(0,start)+"const Row=craftComponent('CompilerBenchRow',{},(inputs:{row:Input<{id:number;label:string}>;position:Input<number>})=>div({'data-row':function*(){return (yield* inputs.row()).id;}},function*(){return (yield* inputs.row()).label+' / '+(yield* __benchCounter.value());}));\n"+source.slice(end);
              source="import {craftService as __benchService,state as __benchState} from '@craft-ts/core';\nlet __benchBump:()=>void=()=>{throw Error('Counter not resolved');};\nconst {BenchCounter:__benchCounter}=__benchService({name:'BenchCounter',providedIn:'global'},function*(){yield* __benchState('value',0,({update})=>{__benchBump=()=>update(value=>value+1);return {bump:__benchBump};});});\n"+source;
              source=source.replace("  else if (action === 'update-one' || action === 'update-tenth')","  else if(action === 'update-tenth') __benchBump();\n  else if (action === 'update-one')");
            }
            if(process.env.CAMPAIGN_LOCAL_FIXTURE === 'true') source=source.replace('const Row = craftComponent(', 'function fixture() {\nconst Row = craftComponent(').replace('const start = performance.now();','return App; }\nconst App = fixture();\nconst start = performance.now();');
            return source;
          },
        }] : []),
        ...(enabled
        ? [
            craftCompiler({
              ...variantOptions,
              onReport: (file, components) =>
                decisions.push({ file, components }),
            }),
          ]
        : []),
      ],
      resolve: { alias: aliases(libraryRoot) },
      build: {
        outDir: dist,
        emptyOutDir: true,
        minify: 'oxc',
        target: 'es2022',
        rolldownOptions: { input: join(app, 'index.html') },
      },
    });
    builds[label] = {
      options: variantOptions,
      mode,
      libraryRoot,
      runtimeSha256: Object.fromEntries(
        await Promise.all(
          [
            'libs/core/src/index.ts',
            'libs/core/src/lib/lifecycle.ts',
            'libs/core/src/lib/host/craft-injector.ts',
            'libs/component/src/lib/render/interpreter.ts',
          ].map(async (file) => [
            file,
            createHash('sha256')
              .update(await readFile(join(libraryRoot, file)))
              .digest('hex'),
          ]),
        ),
      ),
      buildMs: performance.now() - started,
      ...(await bytes(dist)),
      decisions,
    };
    const server = await preview({
      configFile: false,
      root: app,
      logLevel: 'error',
      build: { outDir: dist },
      preview: { host: '127.0.0.1', port: 0 },
    });
    servers.set(label, {
      url: `http://127.0.0.1:${server.httpServer.address().port}/`,
      server,
    });
  }
  browser = await chromium.launch({ headless: true });
  const contracts = [];
  for (const kind of selected) {
    const traces = [];
    for (const [label, { url }] of servers) {
      const { page, context, errors } = await open(url, kind, 100, true),
        trace = [await snapshot(page)];
      await page.evaluate(
        () => (window.__retained = document.querySelector('[data-row]')),
      );
      const reads = [];
      for (const action of actions(kind)) {
        await page.evaluate(() => {
          window.__compilerBench.reads.a = 0;
          window.__compilerBench.reads.b = 0;
        });
        await page.evaluate((a) => window.__compilerBench.run(a), action);
        trace.push(await snapshot(page));
        reads.push(
          await page.evaluate(() => ({ ...window.__compilerBench.reads })),
        );
        if (action === 'update-one' || action === 'reverse')
          assert(
            await page.evaluate(
              () =>
                document.querySelector('[data-row="0"]') === window.__retained,
            ),
            `${label}: retained row identity`,
          );
      }
      if (kind === 'fields') {
        assert.deepEqual(
          reads,
          [
            { a: 1, b: 0 },
            { a: 0, b: 1 },
          ],
          `${label}: independent bindings`,
        );
      }
      await page.evaluate(() => window.__compilerBench.run('destroy'));
      assert.equal(await page.locator('#mount').textContent(), '');
      assert.deepEqual(errors, []);
      traces.push({ label, trace });
      await context.close();
    }
    for (const trace of traces.slice(1))
      assert.deepEqual(
        traces[0].trace,
        trace.trace,
        `${kind}/${trace.label}: DOM equivalence`,
      );
    contracts.push({ case: kind, passed: true, steps: traces[0].trace.length });
  }
  const jobs = [];
  for (let run = 0; run < runs; run++)
    for (const kind of selected)
      for (const count of kind === 'fields' ? [128] : counts)
        for (const label of servers.keys())
          jobs.push({ run, kind, count, label });
  // Seeded shuffle: fresh contexts, interleaved variants and reproducible order.
  let seed = 16112026;
  const random = () => {
    seed = (1664525 * seed + 1013904223) >>> 0;
    return seed / 2 ** 32;
  };
  // Randomized blocks keep both variants of a case adjacent; their order
  // alternates by run to balance order effects during this confirmation.
  const blocks=[];
  for(const job of jobs){
    const previous=blocks.at(-1);
    if(previous&&previous[0].run===job.run&&previous[0].kind===job.kind&&previous[0].count===job.count)previous.push(job);
    else blocks.push([job]);
  }
  for(const block of blocks)if(block[0].run%2)block.reverse();
  for(let i=blocks.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[blocks[i],blocks[j]]=[blocks[j],blocks[i]];}
  jobs.splice(0,jobs.length,...blocks.flat());
  const raw = [];
  for (const job of jobs) {
    const { page, context, errors } = await open(
      servers.get(job.label).url,
      job.kind,
      job.count,
    );
    const data = await page.evaluate(() => ({
      mount: window.__compilerBench.mountMs,
      ready: window.__compilerBench.navigationToReadyMs,
      twoFrames: window.__compilerBench.twoFramesMs,
      nodes: document.getElementById('mount').querySelectorAll('*').length,
    }));
    const samples = {};
    for (let loop = 0; loop < iterations + 2; loop++)
      for (const action of actions(job.kind)) {
        let ms;
        try {
          ms = await page.evaluate(
            (a) => window.__compilerBench.run(a),
            action,
          );
        } catch (error) {
          await writeFile(
            join(output, 'failed-case.json'),
            JSON.stringify({ job, loop, action, errors }, null, 2),
          );
          throw error;
        }
        if (loop >= 2) (samples[action] ??= []).push(ms);
      }
    const cdp = await context.newCDPSession(page);
    await cdp.send('HeapProfiler.collectGarbage');
    data.heapMiB =
      (await cdp.send('Runtime.getHeapUsage')).usedSize / 1024 / 1024;
    data.actions = Object.fromEntries(
      Object.entries(samples).map(([name, values]) => [name, median(values)]),
    );
    assert.deepEqual(errors, []);
    raw.push({ ...job, ...data });
    await context.close();
    if (raw.length % 10 === 0)
      console.log(`${raw.length}/${jobs.length} navigations`);
  }
  const summary = [];
  for (const kind of selected)
    for (const count of kind === 'fields' ? [128] : counts)
      for (const label of servers.keys()) {
        const rows = raw.filter(
          (r) => r.kind === kind && r.count === count && r.label === label,
        );
        summary.push({
          case: kind,
          count,
          label,
          ...Object.fromEntries(
            ['mount', 'ready', 'twoFrames', 'heapMiB'].map((key) => [
              key,
              distribution(rows.map((r) => r[key])),
            ]),
          ),
          actions: Object.fromEntries(
            [...new Set(actions(kind))].map((key) => [
              key,
              distribution(rows.map((r) => r.actions[key])),
            ]),
          ),
        });
      }
  const result = {
    timestamp: new Date().toISOString(),
    base: execFileSync('git', ['rev-parse', 'HEAD'], {
      cwd: root,
      encoding: 'utf8',
    }).trim(),
    sourceSha256,
    environment: {
      cpu: cpus()[0].model,
      platform: platform(),
      release: release(),
      node: process.version,
      chromium: browser.version(),
    },
    runs,
    iterations,
    contracts,
    builds,
    summary,
    raw,
  };
  await writeFile(
    join(output, 'results.json'),
    JSON.stringify(result, null, 2) + '\n',
  );
  console.table(
    summary.map((r) => ({
      case: r.case,
      count: r.count,
      variant: r.label,
      mount: r.mount.median,
      ready: r.ready.median,
      heap: r.heapMiB.median,
    })),
  );
  console.log(join(output, 'results.json'));
} finally {
  await browser?.close();
  for (const { server } of servers.values())
    await new Promise((done) => server.httpServer.close(done));
}

