assertionResults.fullName:
cleanup failures cancels all tasks and notifies all cancellation listeners: class VirtualCraftTemporalRuntime extends BaseCraftTemporalRuntime {
	currentTime;
	/** What `dateNow()` adds to the virtual time: civil time at `initialTime` minus `initialTime`. */
	civilOffset;
	/**
	* `dateOrigin` is the civil time (epoch milliseconds) at `initialTime`: a
	* replay starts its virtual clock at the recording's elapsed time, and its
	* `dateNow()` must still read the hour of the recording, not 1970. Without
	* it, civil time is the virtual time itself.
	*/
	constructor(initialTime = 0, options = {}) {
		super();
		assertFiniteTime(initialTime, "initialTime");
		if (options.dateOrigin !== undefined) assertFiniteTime(options.dateOrigin, "dateOrigin");
		this.currentTime = initialTime;
		this.civilOffset = options.dateOrigin === undefined ? 0 : options.dateOrigin - initialTime;
	}
	now() {
		return this.currentTime;
	}
	dateNow() {
		return this.currentTime + this.civilOffset;
	}
	async advanceBy(milliseconds) {
		assertDelay(milliseconds);
		await this.advanceTo(this.currentTime + milliseconds);
	}
	async advanceTo(time) {
		assertFiniteTime(time, "time");
		if (time < this.currentTime) {
			throw new RangeError("Virtual time cannot move backwards.");
		};
		for (;;) {
			const task = this.takeNextDueTask(time);
			if (!task) break;
			this.currentTime = task.snapshot().dueAt;
			this.runTask(task);
			await Promise.resolve();
		};
		this.currentTime = time;
		await Promise.resolve();
	}
	async advanceToNextTask() {
		const next = this.pendingTasks()[0];
		if (!next) return false;
		await this.advanceTo(next.dueAt);
		return true;
	}
	async runUntilIdle(maxTasks = 1e4) {
		let count = 0;
		while (await this.advanceToNextTask()) {
			count += 1;
			if (count > maxTasks) {
				throw new Error(`Virtual temporal runtime exceeded ${maxTasks} tasks without becoming idle.`);
			}
		}
	}
	reset(time = 0) {
		assertFiniteTime(time, "time");
		this.cancelAll();
		this.currentTime = time;
	}
}

